import * as React from "react";
import { cn } from "@/lib/utils";

/** "Faraway River" gradient. */
export const GradientFarawayRiver_CSS = "linear-gradient(-20deg, #6e45e2 0%, #88d3ce 100%)";

export function GradientFarawayRiver({ className, style, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      className={cn("h-40 w-full rounded-xl", className)}
      style={{ backgroundImage: "linear-gradient(-20deg, #6e45e2 0%, #88d3ce 100%)", ...style }}
      {...props}
    />
  );
}
